export const GRAMMAR = `(* ---- the two texts ---- *)
setup_text      = "all" | expr ;
outcome_text    = event_outcome | expr ;

(* ---- event outcomes ---- *)
event_outcome   = [ "not" ] , event , [ ( "before" | "then" ) , event ] , { clause } ;
event           = "touches" , sum
                | "trades" , ( "above" | "below" ) , sum
                | "closes" , ( "above" | "below" ) , sum , [ "on" , duration ] ;
clause          = "from" , time
                | "by" , ( time | "close" | "session_close" )
                | "within" , duration ;

(* ---- conditions and values ---- *)
expr            = disjunction ;
disjunction     = conjunction , { "or" , conjunction } ;
conjunction     = negation , { "and" , negation } ;
negation        = "not" , negation | relation ;
relation        = sum , [ comp_op , sum
                        | "between" , sum , "and" , sum
                        | [ "not" ] , "in" , "(" , sum , { "," , sum } , ")" ] ;
comp_op         = ">" | ">=" | "<" | "<=" | "=" | "==" | "!=" | "<>" ;
sum             = product , { ( "+" | "-" ) , product } ;
product         = unary , { ( "*" | "/" ) , unary } ;
unary           = "-" , unary | postfix ;
postfix         = primary , { "." , IDENT } ;
primary         = quantity
                | call
                | IDENT
                | "(" , expr , ")" ;
quantity        = ( NUMBER | PARAM ) , [ unit ]
                | ( NUMBER | PARAM ) , "%" , [ "of" , postfix ] ;
unit            = "pt" | "pts" | "point" | "points" | "tick" | "ticks" ;
call            = IDENT , "(" , [ argument , { "," , argument } ] , ")" ;
argument        = [ IDENT , "=" ] , ( time | duration | sum ) ;

(* ---- clock literals ---- *)
time            = TIME ;
duration        = ( NUMBER | PARAM ) , duration_unit
                | PARAM ;                     (* a parameter declared in minutes *)
duration_unit   = "m" | "min" | "mins" | "minute" | "minutes"
                | "h" | "hr" | "hrs" | "hour" | "hours" ;`;

